from taf.ul.kpi_selector.operations.restrictions import Restrictions
from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output


class OperationPrototype(object):
    def __init__(self, bts):
        self.bts = bts
        self.restrictions = Restrictions(self.bts)

    @log_input_and_output
    def check_smod_bbmod_types(self, smod_type, bbmod_types):
        """
        Checks whether given smod and bbmod/bbmods match the ones present on bts.
        :param smod_type: smod type e.g. "ASIK"
        :type smod_type: str
        :param bbmod_types: list of bbmod types, e.g. ["ABIL"]
        :type bbmod_types: list
        :return: True if given smod and bbmods match the ones present on bts
        :rtype: bool
        """
        if self.bts.bbmod_hw_types:
            for bbmod in bbmod_types:
                if bbmod not in self.bts.bbmod_hw_types:
                    return False

        if smod_type not in self.bts.smod_hw_types:
            return False

        if self.bts.bbmod_hw_types:
            return len(self.bts.bbmod_hw_types) == len(bbmod_types)

        return True
